//! Minimal reader for the `.sym` file emitted by `elf2sym`.
//!
//! The format is one `ADDRESS NAME` pair per line, `;` starts a comment:
//!
//! ```text
//! ; generated by elf2sym on 2026-10-30
//! 02000000 __ewram_start
//! 084C13BC PInfoTable
//! ```

use std::fs;
use std::io;
use std::path::Path;

/// A name -> address mapping for one build.
#[derive(Debug, Default, Clone)]
pub struct SymbolTable {
    entries: Vec<(String, u32)>,
}

impl SymbolTable {
    /// Parse a `.sym` file.  Unparsable lines are skipped, not fatal.
    pub fn load(path: impl AsRef<Path>) -> io::Result<Self> {
        let text = fs::read_to_string(path)?;
        Ok(Self::parse(&text))
    }

    pub fn parse(text: &str) -> Self {
        let entries = text
            .lines()
            .filter_map(|line| {
                let line = line.trim();
                if line.is_empty() || line.starts_with(';') {
                    return None;
                }
                let mut it = line.split_whitespace();
                let addr = u32::from_str_radix(it.next()?, 16).ok()?;
                let name = it.next()?.to_string();
                Some((name, addr))
            })
            .collect();
        Self { entries }
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Exact name lookup.
    pub fn find(&self, name: &str) -> Option<u32> {
        self.entries
            .iter()
            .find(|(n, _)| n == name)
            .map(|&(_, addr)| addr)
    }

    /// Smallest symbol address strictly greater than `addr`.
    ///
    /// Lets us infer a table's size from the symbol that follows it.
    pub fn next_after(&self, addr: u32) -> Option<u32> {
        self.entries
            .iter()
            .map(|&(_, a)| a)
            .filter(|&a| a > addr && a < crate::ROM_LIMIT)
            .min()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_and_finds() {
        let sym = SymbolTable::parse(
            "; header\n02000000 __ewram_start\n084C13BC PInfoTable\n084C3E1C IInfoTable\n",
        );
        assert_eq!(sym.len(), 3);
        assert_eq!(sym.find("PInfoTable"), Some(0x084C_13BC));
        assert_eq!(sym.find("nope"), None);
        assert_eq!(sym.next_after(0x084C_13BC), Some(0x084C_3E1C));
    }
}
